import { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

export default function Login() {
  const [form, setForm] = useState({ email: '', password: '' });
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const { login } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = async (event) => {
    event.preventDefault();
    setLoading(true);
    setError('');

    try {
      await login(form.email, form.password);
      navigate('/dashboard');
    } catch (err) {
      setError(err.response?.data?.message || 'Unable to sign in.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="auth-shell">
      <section className="auth-hero">
        <div className="auth-hero__panel">
          <span className="eyebrow">Secure, searchable, accountable</span>
          <h1>Digital Records Management System</h1>
          <p>Store records centrally, track versions, monitor access, and generate compliance reports from one web app.</p>
          <div className="feature-list">
            <div className="feature-list__item">Role-based access control</div>
            <div className="feature-list__item">Advanced document retrieval</div>
            <div className="feature-list__item">Version history and restore</div>
            <div className="feature-list__item">Audit and reporting workspace</div>
          </div>
        </div>
      </section>

      <section className="auth-panel">
        <div className="auth-card">
          <div className="auth-card__header">
            <span className="eyebrow">Sign in</span>
            <h2>Welcome back</h2>
            <p>Use your DRMS account to access records, dashboards, and audit tools.</p>
          </div>

          {error && <div className="message message--error">{error}</div>}

          <form onSubmit={handleSubmit}>
            <div className="field">
              <label>Email address</label>
              <input
                className="input"
                type="email"
                value={form.email}
                onChange={(event) => setForm({ ...form, email: event.target.value })}
                placeholder="you@example.com"
                required
              />
            </div>

            <div className="field">
              <label>Password</label>
              <div className="password-row">
                <input
                  className="input"
                  type={showPassword ? 'text' : 'password'}
                  value={form.password}
                  onChange={(event) => setForm({ ...form, password: event.target.value })}
                  placeholder="Enter your password"
                  required
                />
                <button type="button" className="button button--ghost" onClick={() => setShowPassword((value) => !value)}>
                  {showPassword ? 'Hide' : 'Show'}
                </button>
              </div>
            </div>

            <button type="submit" className="button button--primary button--full" disabled={loading}>
              {loading ? 'Signing in...' : 'Sign in'}
            </button>
          </form>

          <p className="auth-footer">Need access? <Link to="/register">Create an account</Link></p>

          <div className="info-card">
            <h3>Session timeout</h3>
            <p>Inactive sessions automatically expire after 30 minutes to satisfy the SRS security requirement.</p>
          </div>
        </div>
      </section>
    </div>
  );
}
